#include <iostream>
#include <vector>
#include <queue>

using namespace std;

int n;
vector<vector<int>> adj;

pair<int, int> bfs(int start, vector<int>& parent, vector<int>& dist) {
    fill(dist.begin(), dist.end(), -1);
    queue<int> q;
    q.push(start);
    dist[start] = 0;
    parent[start] = 0;

    int farthest_node = start;
    int max_d = 0;

    while (!q.empty()) {
        int u = q.front();
        q.pop();

        if (dist[u] > max_d) {
            max_d = dist[u];
            farthest_node = u;
        }

        for (int v : adj[u]) {
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                parent[v] = u;
                q.push(v);
            }
        }
    }

    return {farthest_node, max_d};
}

int count_at_depth(int u, int p, int d, int target) {
    if (d == target) return 1;
    int cnt = 0;
    for (int v : adj[u]) {
        if (v != p) {
            cnt += count_at_depth(v, u, d + 1, target);
        }
    }
    return cnt;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    if (!(cin >> n)) return 0;

    adj.assign(n + 1, vector<int>());
    for (int i = 0; i < n - 1; ++i) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    vector<int> parent(n + 1), dist(n + 1);

    auto p1 = bfs(1, parent, dist);
    int u = p1.first;

    auto p2 = bfs(u, parent, dist);
    int v = p2.first;
    int D = p2.second;

    vector<int> path;
    int curr = v;
    while (curr != 0) {
        path.push_back(curr);
        curr = parent[curr];
    }

    long long count_pairs = 0;

    if (D % 2 == 0) {
        int k = D / 2;
        int center = path[k];

        vector<long long> counts;
        long long sum = 0;
        long long sum_sq = 0;

        for (int neighbor : adj[center]) {
            long long cnt = count_at_depth(neighbor, center, 1, k);
            counts.push_back(cnt);
            sum += cnt;
            sum_sq += cnt * cnt;
        }

        count_pairs = (sum * sum - sum_sq) / 2;
    } else {
        int k = D / 2;
        int c1 = path[k];
        int c2 = path[k + 1];

        long long cnt1 = count_at_depth(c1, c2, 0, k);
        long long cnt2 = count_at_depth(c2, c1, 0, k);

        count_pairs = cnt1 * cnt2;
    }

    cout << D + 1 << "\n";
    cout << count_pairs << "\n";

    return 0;
}
